        for j in range(len(cb) - 1):
            tiles.append(tuple(tuple(row[cb[j] + 1:cb[j + 1]])
                               for row in grid[rb[i] + 1:rb[i + 1]]))
    counts = {}
    for tile in tiles:
        counts[tile] = counts.get(tile, 0) + 1
    common = max(counts, key=counts.get)
    out = [list(row) for row in common]
    odd_tiles = [tile for tile in tiles if tile != common]
    if odd_tiles:
        odd = odd_tiles[0]
        for r in range(len(common)):
            for c in range(len(common[0])):
                if odd[r][c] != common[r][c]:
